Lemma reserved_top_ref : reserved_top (segments_reserved usegs) = 0xb8000.
Proof. vm_compute. reflexivity. Qed.

(* [comment removed for export] *)
Definition ref_segments : list (Z * Z) := [(0x10000, 0x1b000); (0x2b000, 0x53000); (0x7e000, 0x6000); (0x84000, 0x34000)].
Lemma segments_reserved_ref : segments_reserved usegs = map (fun p => went (fst p) (snd p)) ref_segments.
Proof. vm_compute. reflexivity. Qed.
Lemma reservedZ_segments : reservedZ usegs = ref_segments.
Proof. vm_compute. reflexivity. Qed.

Lemma mminv_init : forall tid brk mbase sp lim inp,
  mminv (with_tid tid (init_model (segments_reserved usegs) brk mbase sp lim inp)).
Proof. intros. split; reflexivity. Qed.

